INSERT INTO `pages` (`slug`, `content`) VALUES ('enologists', '{"heading":{"eyebrow":{"en":"The people of Badagoni","ka":""},"title":{"en":"Enologists.","ka":""},"subtitle":{"en":"Georgian wine is a shared craft. Meet the people whose knowledge, research, and daily work shape the character of every bottle.","ka":""}},"people":[{"firstName":{"en":"Dr. Donato","ka":""},"lastName":{"en":"Lanati","ka":""},"role":{"en":"Chief enologist","ka":""},"image":"/images/donato-lanati.webp","description":{"en":"Badagoni’s chief enologist and head of Italy’s Enosis Meraviglia research centre. His work brings scientific research into the vineyard and cellar, with a focus on preserving the character of each Georgian grape variety.","ka":""}},{"firstName":{"en":"Sandro","ka":""},"lastName":{"en":"Kumsiashvili","ka":""},"role":{"en":"Chief winemaker","ka":""},"image":"/images/sandro-kumsiashvili.webp","description":{"en":"Sandro oversees every stage of production, from vinification and fermentation to laboratory control and bottling. His work connects daily precision with the character of both contemporary and traditional qvevri wines.","ka":""}},{"firstName":{"en":"Salome","ka":""},"lastName":{"en":"Salakaia","ka":""},"role":{"en":"Enologist","ka":""},"image":"/images/salome-salakaia.webp","description":{"en":"An enologist trained at the University of Turin, with practical experience in Italian wineries and at Enosis Meraviglia. Her work combines laboratory analysis and sensory evaluation across white, rosé, sparkling, and red wines.","ka":""}},{"firstName":{"en":"Paolo","ka":""},"lastName":{"en":"Lavagna","ka":""},"role":{"en":"Enologist","ka":""},"image":"/images/paolo-lavagna.webp","description":{"en":"Educated at the Oenological School of Alba and the University of Turin, Paolo brings experience in cellar work and laboratory analysis. His approach connects technical knowledge, respect for tradition, and an understanding of wine drinkers.","ka":""}}],"closing":{"eyebrow":{"en":"From the cellar to the table","ka":""},"heading":{"en":"Meet the wines.","ka":""}}}');
